// Disposable loopback-only native-menu/permission fixture. Type q on stdin to stop.
import http from 'node:http';
const server=http.createServer((req,res)=>{res.writeHead(200,{'Content-Type':'text/html; charset=utf-8'});res.end(`<!doctype html><html lang="en"><title>Wiek 0.3 native UI fixture</title><style>body{font:20px system-ui;padding:48px;background:#fff;color:#172033}a,button,input{display:block;margin:24px 0}button{padding:12px 20px;font:inherit}</style><h1>${req.url==='/next'?'Opened native menu link':'Wiek native browser fixture'}</h1><p>This page is served only on this computer for browser QA.</p><a href="/next">Open this local fixture in a new tab</a><button onclick="Notification.requestPermission().then(value=>document.querySelector('#permission-status').textContent='Notification decision: '+value)">Request fixture notification permission</button><p id="permission-status" role="status">No notification has been requested.</p><input aria-label="Editable fixture text" value="Local editing and spelling fixture"></html>`);});
server.listen(0,'127.0.0.1',()=>console.log(JSON.stringify({pid:process.pid,url:`http://127.0.0.1:${server.address().port}/`})));
process.stdin.setEncoding('utf8');process.stdin.on('data',data=>{if(data.trim()==='q')server.close(()=>process.exit());});
